import { render } from "./engine";

describe("render", () => {
  test("escapes double braces and preserves triple braces", () => {
    const data = { value: `&<>"'` };
    expect(render("{{value}}|{{{value}}}", data)).toBe("&amp;&lt;&gt;&quot;&#39;|&<>\"'");
